Arguments:
$root = 'artifacts/ecs-relations/measurements/controlled-r23'
$rows = foreach ($submission in (Get-Content -Raw (Join-Path $root 'submissions.json') | ConvertFrom-Json)) {
    $report = Get-Content -Raw $submission.Report | ConvertFrom-Json
    $sides = foreach ($side in @('relation','handwritten')) {
        $samples = @($report.RawSamples | Where-Object Side -eq $side)
        [pscustomobject]@{
            Side=$side; Samples=$samples.Count; Rounds=@($samples.Round | Select-Object -Unique).Count
            Frames=@($samples.Frame | Select-Object -Unique).Count
            SideOrderMismatches=@($samples | Where-Object { $_.SideOrder -ne $(if ($_.Round % 2 -eq 0) { 'E/H' } else { 'H/E' }) }).Count
            OutputPairCounts=@($samples.OutputPairCount | Select-Object -Unique)
            FrameAllocatedBytes=@($samples.FrameAllocatedBytes | Sort-Object -Unique)
            Gen0=($samples | Measure-Object Gen0 -Sum).Sum
            Gen1=($samples | Measure-Object Gen1 -Sum).Sum
            Gen2=($samples | Measure-Object Gen2 -Sum).Sum
            DataWriteTicks=@($samples.DataWriteTicks | Select-Object -Unique)
        }
    }
    [pscustomobject]@{ CaseId=$submission.CaseId; SourceCommit=$report.Device.SourceCommit
        Equal=$report.Equivalence.Equal; ColdSamples=$report.ColdSamples.Count; Input=$report.Input; Sides=@($sides) }
}
$rows | ConvertTo-Json -Depth 10 | Set-Content -LiteralPath 'docs/evidence/ECS-Relations-2026-10-19/controlled-r23/sample-audit.json' -Encoding utf8
[pscustomobject]@{Cases=@($rows).Count; Equal=@($rows | Where-Object Equal).Count; Sources=@($rows.SourceCommit | Select-Object -Unique); ColdCounts=@($rows.ColdSamples | Select-Object -Unique); SampleCounts=@($rows.Sides.Samples | Select-Object -Unique); OrderMismatches=($rows.Sides | Measure-Object SideOrderMismatches -Sum).Sum; Gen0=($rows.Sides | Measure-Object Gen0 -Sum).Sum; Gen1=($rows.Sides | Measure-Object Gen1 -Sum).Sum; Gen2=($rows.Sides | Measure-Object Gen2 -Sum).Sum} | ConvertTo-Json -Depth 5
